content.css:
:host {font-family:Roboto,sans-serif;font-variant-numeric:tabular-nums;}
.pinol-flow {height:auto!important;max-height:none!important;contain:layout style;flex-shrink:0;}
.pinol-flow > inner {flex:none;}
.text-container {--alpha-fill-off:0;}
.pinol-cue > inner {border-radius:5rem;overflow:hidden;}
.pinol-cue > inner > .widget:not(.pinol-cue-fill) {position:relative;z-index:1;}
.pinol-cue > inner > .pinol-cue-fill {position:absolute!important;top:0!important;left:0!important;min-height:0!important;z-index:0!important;}
.navigation {background:#26262b;}
.tablink {color:#a4a4ae;}
.tablink.on {color:#ececf0;box-shadow:inset 0 -2rem #4cd964;}
@media screen and (min-width:1000px) {
 .pinol-dashboard > inner {grid-template-columns:minmax(0,1.6fr) minmax(320rem,1fr)!important;}
}
